<template><section v-loading="loading"><el-alert v-if="error" title="报账信息加载失败" type="error" :closable="false"/><div class="zj-summary">报账共 {{total}} 笔，合计 {{money(summary.totalAmount)}} 元；待核验 {{money(summary.pendingAmount)}} 元；已支付 {{money(summary.paidAmount)}} 元</div><el-alert v-for="(s,i) in legacy" :key="i" :title="'历史账面汇总：'+money(JSON.parse(s.snapshotJson).project_cost)+'元（保留原账面值，与实际明细合计分别展示）'" type="info" :closable="false"/><el-table :data="users"><el-table-column prop="label" label="报账人"/><el-table-column prop="records" label="笔数"/><el-table-column label="金额"><template #default="{row}">{{money(row.amount)}}</template></el-table-column></el-table><el-table :data="rows" empty-text="暂无此项目的报账"><el-table-column prop="expenseDate" label="日期" width="120"/><el-table-column prop="claimantName" label="报账人" width="120"/><el-table-column label="金额" width="140"><template #default="{row}">{{money(row.amount)}}</template></el-table-column><el-table-column prop="purpose" label="用途" min-width="200"/><el-table-column label="状态" width="100"><template #default="{row}">{{statuses[row.status]}}</template></el-table-column><el-table-column label="发票"><template #default="{row}"><el-link v-for="(f,i) in (row.invoices||'').split(',').filter(Boolean)" :key="f" :href="fileUrl(f)" target="_blank">查看{{i+1}}</el-link></template></el-table-column></el-table><el-pagination v-model:current-page="page" :page-size="20" :total="total" layout="total,prev,pager,next" @current-change="load"/></section></template><script setup>
import {projectChildren} from '@/api/workProject';import {money} from '@/api/projectFinance';import {fileUrl} from '@/utils/files';const props=defineProps({projectId:[String,Number]}),page=ref(1),rows=ref([]),users=ref([]),summary=ref({}),legacy=ref([]),total=ref(0),loading=ref(false),error=ref(false);const statuses={pending:'待核验',paid:'已支付',rejected:'不予报销'};async function load(){loading.value=true;error.value=false;try{const r=await projectChildren(props.projectId,'expenses',{pageNum:page.value,pageSize:20});rows.value=r.rows;total.value=r.total;summary.value=r.summary;users.value=r.users;legacy.value=r.legacySummary||[]}catch{error.value=true;rows.value=[]}finally{loading.value=false}}onMounted(load);watch(()=>props.projectId,()=>{page.value=1;load()});
</script>
